#!/usr/bin/env ruby
# frozen_string_literal: true

require "yaml"

# Code generator for Prism AST serialization walk checks (node_serialize_walk.inc).
module PrismHarnessCodegen
  module_function

  def generate_serialize_walk(config_path, out_path)
    tmp_path = nil
    config = YAML.safe_load_file(config_path)
    lines = [
      "/*----------------------------------------------------------------------------*/",
      "/* This file is generated by harnesses/prism/gen_serialize_walk.rb from       */",
      "/* config.yml and should not be modified manually.                            */",
      "/*----------------------------------------------------------------------------*/",
      ""
    ]

    config.fetch("nodes").each do |node|
      human = node.fetch("name").gsub(/(?<=.)[A-Z]/, "_\\0").downcase
      has_flags = node["flags"] && !node["flags"].empty?
      fields = node["fields"] || []

      lines << "    case PM_#{human.upcase}: {"
      if has_flags
        lines << "        SERIALIZE_WALK_VARUINT();"
      else
        lines << "#if !PRISM_SERIALIZE_ONLY_SEMANTICS_FIELDS"
        lines << "        SERIALIZE_WALK_VARUINT();"
        lines << "#endif"
      end

      fields.each do |field|
        case field.fetch("type")
        when "node", "node?"
          # Child subtrees precede the node record in post-order serialization.
        when "node[]", "constant", "constant?", "uint32"
          lines << "        SERIALIZE_WALK_VARUINT();"
        when "constant[]"
          lines << "        SERIALIZE_WALK_CONST_LIST();"
        when "location"
          lines << "#if !PRISM_SERIALIZE_ONLY_SEMANTICS_FIELDS"
          lines << "        SERIALIZE_WALK_LOC();"
          lines << "#endif"
        when "location?"
          lines << "#if !PRISM_SERIALIZE_ONLY_SEMANTICS_FIELDS"
          lines << "        SERIALIZE_WALK_OPT_LOC();"
          lines << "#endif"
        when "string"
          lines << "        SERIALIZE_WALK_STRING();"
        when "integer"
          lines << "        SERIALIZE_WALK_INTEGER();"
        when "uint8"
          lines << "        SERIALIZE_WALK_U8();"
        when "double"
          lines << "        SERIALIZE_WALK_SWAP_U64();"
        else
          abort "Unsupported field type in #{node["name"]}: #{field.inspect}"
        end
      end
      lines << "        break;"
      lines << "    }"
    end

    contents = "#{lines.join("\n")}\n"
    abort("Non-ASCII character in generated #{out_path}") unless contents.ascii_only?

    tmp_path = "#{out_path}.tmp.#{Process.pid}"
    File.write(tmp_path, contents)
    File.rename(tmp_path, out_path)
    out_path
  ensure
    File.delete(tmp_path) if tmp_path && File.exist?(tmp_path)
  end

  def run_serialize_walk_cli(argv = ARGV)
    repo_root = File.expand_path("../..", __dir__)
    default_prism = ENV["PRISM_A_DIR"] || File.join(repo_root, "tmp/fuzz/build/targets/prism_a")
    config_path = argv[0] || File.join(default_prism, "config.yml")
    out_path = argv[1] || File.join(repo_root, "tmp/fuzz/build/targets/gen/prism_a/node_serialize_walk.inc")
    generate_serialize_walk(config_path, out_path)
  end

  alias_method :run_cli, :run_serialize_walk_cli
  module_function :run_cli
end

if __FILE__ == $PROGRAM_NAME
  PrismHarnessCodegen.run_cli(ARGV)
end
